create extension if not exists "pgcrypto";
create type seller_type as enum ('company','facebook_page','broker','owner');
create type property_status as enum ('draft','pending','published','rejected','archived');
create table if not exists sellers(id uuid primary key default gen_random_uuid(),user_id uuid unique,seller_type seller_type not null,display_name text not null,legal_name text,commercial_register text,license_number text,address text,years_experience int,facebook_url text,followers int,whatsapp text,email text,description text,verified boolean not null default false,verification_status text not null default 'unverified',created_at timestamptz not null default now());
create table if not exists properties(id uuid primary key default gen_random_uuid(),seller_id uuid references sellers(id) on delete cascade,title text not null,deal_type text not null check(deal_type in ('sale','rent')),type text not null,city text not null,area text not null,address text,price numeric not null,price_currency text not null default 'EGP',negotiable boolean default false,size_m2 numeric,rooms int,bathrooms int,floor int,build_year int,finishing text,payment_method text,ownership_status text,description text,image_url text,video_url text,status property_status not null default 'pending',verified boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists favorites(user_id uuid not null,property_id uuid not null references properties(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,property_id));
create table if not exists reports(id uuid primary key default gen_random_uuid(),property_id uuid references properties(id) on delete cascade,reporter_id uuid,reason text not null,details text,status text not null default 'open',created_at timestamptz not null default now());
create table if not exists leads(id uuid primary key default gen_random_uuid(),property_id uuid references properties(id) on delete cascade,seller_id uuid references sellers(id) on delete cascade,buyer_id uuid,channel text not null,created_at timestamptz not null default now());
alter table sellers enable row level security;alter table properties enable row level security;alter table favorites enable row level security;alter table reports enable row level security;alter table leads enable row level security;
create policy "public can view published properties" on properties for select using(status='published');
create policy "public can view sellers" on sellers for select using(true);
-- Add authenticated INSERT/UPDATE policies and admin-only policies after Supabase Auth is enabled.
